{"implementation": "def solve(case):
    # Validate top-level required fields
    if 'threshold' not in case:
        raise ValueError("Missing required field: threshold")
    if 'calls' not in case:
        raise ValueError("Missing required field: calls")

    threshold = case['threshold']
    calls = case['calls']

    if not isinstance(calls, list):
        raise ValueError("'calls' must be a list")

    diagnostics = []
    accepted_call_ids = []

    for call in calls:
        for field in ('call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable'):
            if field not in call:
                raise ValueError(f"Call is missing required field: {field}")

        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        prediction_tokens = call['prediction_tokens']
        parseable = call['parseable']

        if not isinstance(call_id, str):
            raise ValueError(f"call_id must be a string, got: {type(call_id)}")
        if not isinstance(parseable, bool):
            raise ValueError(f"parseable must be a bool for call {call_id}")
        if not isinstance(prediction_tokens, (int, float)):
            raise ValueError(f"prediction_tokens must be numeric for call {call_id}")

        tokens = max(prediction_tokens, 1)
        gain = loss_without - loss_with
        normalized_gain = gain / tokens

        accepted = parseable and normalized_gain >= threshold

        diagnostics.append({
            'call_id': call_id,
            'normalized_gain': round(normalized_gain, 8),
            'accepted': accepted
        })

        if accepted:
            accepted_call_ids.append(call_id)

    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }
